def resolve(path, cwd, links):
    # Track the number of links followed to prevent infinite loops
    link_count = [0]  # Use list to allow modification in nested function

    def resolve_helper(p, current_dir):
        # Normalize: split by '/', filter out empty and '.' components
        parts = [comp for comp in p.split('/') if comp and comp != '.']

        # Start from current directory
        result_parts = current_dir.split('/')[1:]  # Skip first empty string from leading '/'

        for part in parts:
            if part == '..':
                # Move to parent
                if result_parts:
                    result_parts.pop()
            else:
                # Append the component
                result_parts.append(part)

            # Build current path
            current_path = '/' + '/'.join(result_parts) if result_parts else '/'

            # Check if this path is a symlink
            if current_path in links:
                link_count[0] += 1
                if link_count[0] > 8:
                    return None

                # Get the link target
                target = links[current_path]

                # Determine the directory where the symlink is
                if current_path == '/':
                    link_dir = '/'
                else:
                    link_dir = '/' + '/'.join(result_parts[:-1]) if len(result_parts) > 1 else '/'

                # If target is absolute, start from root; otherwise relative to link_dir
                if target.startswith('/'):
                    target_dir = '/'
                else:
                    target_dir = link_dir

                # Recursively resolve the target
                result_path = resolve_helper(target, target_dir)
                if result_path is None:
                    return None

                # Continue with remaining parts from the resolved link target
                result_parts = result_path.split('/')[1:] if result_path != '/' else []

        # Build final path
        final_path = '/' + '/'.join(result_parts) if result_parts else '/'
        return final_path

    try:
        # Normalize input path
        if path.startswith('/'):
            # Absolute path
            start_dir = '/'
        else:
            # Relative path - relative to cwd
            start_dir = cwd

        result = resolve_helper(path, start_dir)
        return result
    except:
        return None

